  -- Менеджер модификаторов: обновляет состояние модификаторов на каждом тике Heartbeat
  namespace.class("ModifierManager", function (namespace)
    local activeModifiers, isInitialized, Init, AddModifier, RemoveModifier, Update, RecalculateCharacterStats, static
    static = function (this)
      activeModifiers = ListModifierBase()
    end
    isInitialized = false
    Init = function ()
      if isInitialized then
        return
      end
      isInitialized = true

      -- Подключаем физический цикл обновления через RunService.Heartbeat
      Roblox.Game.RunService.Heartbeat:Connect(function (step)
        local dt = 0.016666666666666666 --[[1.0 / 60.0]]
