      end)
    end
    AddModifier = function (target, modifier)
      Init()
      if target == nil or modifier == nil then
        return
      end

      if not target.ActiveModifiers:Contains(modifier) then
        target.ActiveModifiers:Add(modifier)
      end

      if not activeModifiers:Contains(modifier) then
        activeModifiers:Add(modifier)
      end

      RecalculateCharacterStats(target)
    end
    RemoveModifier = function (target, modifier)
      if target ~= nil then
        target.ActiveModifiers:Remove(modifier)
        RecalculateCharacterStats(target)
      end
      activeModifiers:Remove(modifier)
    end
    Update = function (deltaTime)
      if #activeModifiers == 0 then
        return
      end

      local toRemove = ListModifierBase()

      for i = 0, #activeModifiers - 1 do
        local continue
        repeat
          local mod = activeModifiers:get(i)
          if not mod.IsActive or mod.Target == nil or mod.Target.Model == nil or mod.Target.Model.Parent == nil then
            toRemove:Add(mod)
            continue = true
            break
          end

          mod.ElapsedTime = mod.ElapsedTime + deltaTime

          -- 1. Обновление физических контроллеров движения (MotionBase)
          local motion = mod
          if System.is(motion, RobloxCSharpFramework.MotionBase) then
            motion:UpdateMotion(deltaTime)
          end

          -- 2. Периодический тик (OnIntervalThink)
          if mod.ThinkInterval > 0 then
            if mod.ElapsedTime - mod.LastThinkTime >= mod.ThinkInterval then
              mod.LastThinkTime = mod.ElapsedTime
              mod:OnIntervalThink()
            end
          end

          -- 3. Проверка истечения времени действия (Duration)
          if mod.Duration > 0 and mod.ElapsedTime >= mod.Duration then
            toRemove:Add(mod)
